/**
 * Read Aloud's grapheme-to-phoneme pass (src/lib/g2p), against misaki itself.
 *
 * The pass is a port of misaki, the G2P Kokoro was trained with, and a port is where
 * a silent error lives: a wrong stress or a dropped "the" doesn't throw, it just sounds
 * a little off. So every case in voice-reference.json carries misaki's own answer for
 * both dialects, generated by scripts/dev/misaki-reference.py from the real package,
 * and the port must give the same one. The fallback is off for those cases, as it is
 * in the reference.
 *
 * Left out of the reference, because they need the whole sentence parsed (spaCy does
 * that for misaki): a past-tense "read" after a name, a verb at the start of a sentence
 * ("Close the door"), and a word that is both noun and verb back to back ("the dove
 * dove"). The port takes the dictionary's default reading for those.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'

import { ok } from './assert.mjs'

const { createG2P } = await import('../../src/lib/g2p/g2p.ts')
const { normalizeText } = await import('../../src/lib/g2p/normalize.ts')
const { cardinal, ordinal, year, decimal } = await import('../../src/lib/g2p/numbers.ts')
const { toMisaki, guess } = await import('../../src/lib/g2p/fallback.ts')
const { phonemesToTokens } = await import('../../src/lib/readAloudVoice.ts')

const lexicon = (name) => JSON.parse(readFileSync(`src/lib/g2p/data/${name}_gold.json`, 'utf8'))
const US = lexicon('us')
const GB = lexicon('gb')
const strictUS = createG2P(US, { british: false, fallback: false })
const strictGB = createG2P(GB, { british: true, fallback: false })
const us = createG2P(US, { british: false })
const gb = createG2P(GB, { british: true })

const squash = (s) => s.replace(/\s+/g, ' ').trim()
const label = (text) => JSON.stringify(text.length > 46 ? `${text.slice(0, 46)}…` : text)

/* ---------------- against misaki ---------------- */

const reference = JSON.parse(readFileSync('tests/unit/voice-reference.json', 'utf8'))
for (const { text, us: wantUS, gb: wantGB } of reference.cases) {
  // A case normalizeText would rewrite isn't comparing the same input on both sides.
  ok(`reference input is already normal: ${label(text)}`, normalizeText(text) === text)
  ok(`US matches misaki: ${label(text)}`, squash(strictUS(text)) === squash(wantUS))
  ok(`GB matches misaki: ${label(text)}`, squash(strictGB(text)) === squash(wantGB))
}

/* ---------------- numbers, against num2words ---------------- */

// num2words' own output, copied from Python 3 `num2words`.
const CARDINALS = {
  0: 'zero', 21: 'twenty-one', 105: 'one hundred and five', 1001: 'one thousand and one',
  1100: 'one thousand, one hundred', 1234: 'one thousand, two hundred and thirty-four',
  1000000: 'one million', 1000001: 'one million and one',
  123456789012: 'one hundred and twenty-three billion, four hundred and fifty-six million, seven hundred and eighty-nine thousand and twelve',
}
for (const [n, words] of Object.entries(CARDINALS)) ok(`cardinal ${n}`, cardinal(n) === words)

const ORDINALS = { 5: 'fifth', 12: 'twelfth', 21: 'twenty-first', 40: 'fortieth', 100: 'one hundredth', 101: 'one hundred and first' }
for (const [n, words] of Object.entries(ORDINALS)) ok(`ordinal ${n}`, ordinal(n) === words)

const YEARS = {
  999: 'nine ninety-nine', 1000: 'one thousand', 1066: 'ten sixty-six', 1100: 'eleven hundred',
  1801: 'eighteen oh-one', 1905: 'nineteen oh-five', 1984: 'nineteen eighty-four',
  2000: 'two thousand', 2005: 'two thousand and five', 2010: 'twenty ten', 2024: 'twenty twenty-four',
}
for (const [n, words] of Object.entries(YEARS)) ok(`year ${n}`, year(Number(n)) === words)

ok('decimal 3.14', decimal('3.14') === 'three point one four')
ok('decimal 2.50 drops the trailing zero', decimal('2.50') === 'two point five')
ok('decimal 1.0 is a whole number', decimal('1.0') === 'one')

/* ---------------- what misaki leaves to spaCy ---------------- */

ok('a clock time is two numbers', squash(us('Meet at 9:30.')) === squash(us('Meet at 9 30.')))
ok('a time on the hour', normalizeText('at 10:00') === "at 10 o'clock")
ok('a time with a leading zero minute', normalizeText('at 3:05') === 'at 3 oh 5')
ok('"St." before a name is Saint', normalizeText('St. Paul') === 'Saint Paul')
ok('"St." after a name is Street', normalizeText('Elm St. near') === 'Elm Street near')
ok('an abbreviation leaves no full stop behind', !us('Ask Prof. Plum.').slice(0, -1).includes('.'))
ok('"replied" reads from "reply"', us('replied') === 'ɹəplˈId')
ok('"lived" is the verb', us('They lived there.').includes('lˈɪvd'))
ok('"had read" is the past participle', us('had read').endsWith('ɹˈɛd'))
ok('"to record" is the verb', us('to record').endsWith('ɹəkˈɔɹd'))
ok('"the record" is the noun', us('the record').endsWith('ɹˈɛkəɹd'))

/* ---------------- the fallback ---------------- */

// The symbols misaki's EN_PHONES.md lists for each dialect, plus Kokoro v1.0's flap
// and the punctuation it reads.
const US_SYMBOLS = new Set('AIOWYbdfhijklmnpstuvwzæðŋɑɔəɛɜɡɪɹɾʃʊʌʒʤʧˈˌθᵊᵻT')
const GB_SYMBOLS = new Set('AIQWYabdfhijklmnpstuvwzðŋɑɒɔəɛɜɡɪɹʃʊʌʒʤʧˈˌːθᵊ')
const MARKS = new Set(' ;:,.!?—…"“”()ɐ')
const within = (ps, symbols) => [...ps].every((c) => symbols.has(c) || MARKS.has(c))

const NAMES = ['Hermione', 'Daenerys', 'Tolkien', 'Netherfield', 'Xyzzy', 'Pemberley', 'café', 'Zoë']
for (const name of NAMES) {
  const american = guess(name, false)
  const british = guess(name, true)
  ok(`a guess for ${name}`, american.length > 0 && british.length > 0)
  ok(`${name}: US symbols only`, within(american, US_SYMBOLS))
  ok(`${name}: GB symbols only`, within(british, GB_SYMBOLS))
}
ok('a guess puts stress before its vowel', toMisaki('ˈdɑɹsi', false) === 'dˈɑɹsi')
ok('diphthongs become single letters', toMisaki('ˈhoʊm', false) === 'hˈOm' && toMisaki('ˈhoʊm', true) === 'hˈQm')
ok('stressed NURSE keeps its r in America', toMisaki('ˈbɝd', false) === 'bˈɜɹd')
ok('unstressed NURSE reduces', toMisaki('ˈbʌtɝ', false) === 'bˈʌtəɹ')
ok('RP lengthens a stressed FLEECE vowel', toMisaki('ˈsin', true) === 'sˈiːn')

const PROSE = 'Hermione Granger walked through the old library at Netherfield, where Mr. Darcy had read every book twice.'
ok('prose with names: US symbols only', within(us(PROSE), US_SYMBOLS))
ok('prose with names: GB symbols only', within(gb(PROSE), GB_SYMBOLS))
ok('a name is spoken, not skipped', us('Daenerys').length > 3)

/* ---------------- tokenization ---------------- */

// A stand-in vocabulary; the real one is the model's and is fetched, never written
// down. What is checked here is the padding and the dropping, not the values.
const vocab = { a: 10, b: 11, c: 12, 'ˈ': 20 }

ok('padding brackets the ids', JSON.stringify(phonemesToTokens('abc', vocab)) === '[0,10,11,12,0]')
ok('an empty utterance is still padded', JSON.stringify(phonemesToTokens('', vocab)) === '[0,0]')
ok(
  'a phoneme the model does not know is dropped, not guessed',
  JSON.stringify(phonemesToTokens('aXbˈ', vocab)) === '[0,10,11,20,0]'
)

/* ---------------- no GPL in the app ---------------- */

// `phonemizer` is eSpeak NG compiled to WebAssembly, which is GPL, and `kokoro-js`
// imports it. Neither may be imported by anything that ships: kokoro-js is a dev
// dependency for its voice files only (see THIRD-PARTY-NOTICES.md).
const sources = []
const walk = (dir) => {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name)
    if (statSync(path).isDirectory()) walk(path)
    else if (/\.(jsx?|tsx?|mjs)$/.test(name)) sources.push(path)
  }
}
walk('src')
const offenders = sources.filter((path) => /from ['"](?:phonemizer|kokoro-js)['"]|import\(['"](?:phonemizer|kokoro-js)['"]\)/
  .test(readFileSync(path, 'utf8')))
ok(`nothing in src imports phonemizer or kokoro-js${offenders.length ? `: ${offenders.join(', ')}` : ''}`, offenders.length === 0)
